import React, { useEffect } from "react";
import { GetListOfTeams, GetTeamStatsById } from "../Services/ApiHandler";
import { ConvertToListOfTeams } from "../Data/Helpers/TeamHelpers";
import { Button, Col, Container, Row } from "react-bootstrap";
import { Link } from "react-router-dom";

export default function TeamList() {
  const teamListData = React.useRef<any[]>([]);
  useEffect(() => {
    GetListOfTeams().then((response) => {
      let rawData: any[] = response.data.data;
      for (let i = 0; i < rawData.length; i++) {
        if (rawData[i].rawTricode === "NHL") {
          rawData = rawData.splice(i + 1, rawData.length - 1);
          teamListData.current = rawData;
        }
      }
    });
    GetTeamStatsById("").then((response) => {
      const rawData: any[] = response.data.data;
      const data = ConvertToListOfTeams(teamListData.current, rawData);
      console.log(data);
    });
  });
  return (
    <Container>
      <Row id="standing-page-header">
        <h2>Teams</h2>
      </Row>
      <Row id="standings-page-header-menu">
        <Col xs={3} md={4} className="standings-page-header-menu-item">
          <Link to="/">
            <Button className="header-menu-btn">Home</Button>
          </Link>
        </Col>
        <Col xs={3} md={4} className="standings-page-header-menu-item">
          <Link to="/standings">
            <Button className="header-menu-btn">Standings</Button>
          </Link>
        </Col>
        <Col xs={3} md={4} className="standings-page-header-menu-item">
          <Link to="">
            <Button className="header-menu-btn">Team List</Button>
          </Link>
        </Col>
      </Row>
    </Container>
  );
}
